export const VERMICELLI_FRONTMATTER = "number: 1\ntitle: \"Egyptian Vermicelli Milk Pudding, Boudie's Way\"\nshortTitle: \"Vermicelli Milk Pudding\"\nenglishTitle: \"Egyptian Vermicelli Milk Pudding\"\ndescription: \"Golden vermicelli simmered in creamy milk. A recipe you adjust by taste and texture, with a special oven-pot variation.\"\nheadline: \"Thick enough to eat with a fork.\"\ncoverIntro: \"I like my vermicelli pudding thick and creamy, with soft strands that have not turned mushy. The secret isn't strict measurements: it is stirring, adding more milk, and tasting until the texture is exactly how you want it.\"\nauthor: \"Boudie\"\ncategories: [\"Egyptian desserts\", \"Home cooking\"]\ntags: [\"vermicelli\", \"milk\", \"cream\", \"dessert\", \"Egyptian\"]\nfeatured: true\npick: true\ningredients:\n  - text: \"One cup of vermicelli.\"\n  - text: \"A tablespoon of traditional baladi ghee, or to taste.\"\n  - text: \"Fresh or UHT milk, as needed.\"\n  - text: \"Cream, to taste.\"\n  - text: \"Sugar, to taste.\"\n  - text: \"A few drops of vanilla, optional.\"\nsteps:\n  - title: \"Toast the vermicelli\"\n    body:\n      - \"Put one cup of vermicelli into a pot over heat with a tablespoon of baladi ghee, or your preferred amount.\"\n      - \"Stir continuously until the vermicelli turns golden.\"\n  - title: \"Add the milk gradually\"\n    body:\n      - \"Once the vermicelli is golden, gradually pour in the milk.\"\n      - \"Fresh milk or long-life UHT milk both work.\"\n      - \"Add cream and sugar to your taste.\"\n  - title: \"Keep stirring\"\n    body:\n      - \"Stir over low heat so the milk does not stick or burn.\"\n      - \"As the mixture thickens, add more milk a little at a time. Adjust the sugar and cream if needed.\"\n      - \"Repeat until the vermicelli is tender and the pudding thick and creamy.\"\n  - title: \"Find your ideal consistency\"\n    body:\n      - \"Aim for tender vermicelli, without turning it mushy.\"\n      - \"The milk should be rich and creamy, never dry.\"\n      - \"Taste throughout until you are happy with the flavour.\"\n  - title: \"The final touch\"\n    body:\n      - \"Add a few drops of vanilla if you enjoy the aroma; it is optional.\"\n      - \"Serve while hot, straight from the stove, when the texture is at its best.\"\ntips:\n  - title: \"Scrape the edges of the pot\"\n    text: \"Stir around the bottom and sides as well: vermicelli can stick and burn there.\"\n  - title: \"Too much sugar?\"\n    text: \"Add milk gradually while stirring to soften the sweetness.\"\n  - title: \"Too thick or sticky?\"\n    text: \"Slowly add more milk and stir until the mixture loosens and turns creamy again. If the vermicelli is overcooked, milk improves the texture of the pudding but cannot undo the softness of the strands.\"\n  - title: \"Serve hot\"\n    text: \"This pudding thickens further as it cools, so serve it straight away.\"\nvariation:\n  title: \"Extra trick: Oven-browned vermicelli pots\"\n  steps:\n    - \"Divide the cooked vermicelli pudding into small oven-safe clay pots.\"\n    - \"Place a spoonful of cream on each pot.\"\n    - \"Cover each with a little of the pudding's creamy milk.\"\n    - \"Place under the oven grill until the top turns golden.\"\n    - \"Keep a close eye on it; cream browns quickly.\"\n";
